mapper.select:
SELECT 
FROM mt_shop_right
WHERE shop_id = #{shopId}
  AND service_code = #{serviceCode}
LIMIT 1

SELECT shop_id AS shopId, MAX(expire_at) AS expectedExpireAt
FROM mt_shop_right
WHERE shop_id > #{lastShopId}
  AND service_code IN ('VIP_CODE', 'H5_PROMOTION', 'MT_APP_OPEN_ONLY', 'IM_AUTO_REPLY_ONLY')
  AND type = 2
  AND expire_at IS NOT NULL
  AND expire_at > #{now}
GROUP BY shop_id
ORDER BY shop_id ASC
LIMIT #{limit}

mapper.insert:
